import argparse,hashlib,json,subprocess,tarfile
from pathlib import Path
from datetime import datetime,timezone
p=argparse.ArgumentParser();p.add_argument('--root',required=True);a=p.parse_args();root=Path(a.root);out=root/'exports/final-hostap-runtime-v3';out.mkdir();selected=[];records=[]
for dirname,subdir,exe in [('hostap-pq-delay-auth','hostapd-2.12/hostapd','hostapd'),('hostap-pq-delay-auth','wpa_supplicant-2.12/wpa_supplicant','wpa_supplicant'),('hostap-delay-reproduced','wpa_supplicant-2.12/wpa_supplicant','wpa_supplicant'),('hostap-all-mka','wpa_supplicant-2.12/wpa_supplicant','wpa_supplicant')]:
 for name in [exe,'.config']:
  f=root/dirname/subdir/name
  if f.is_file():selected.append(f);records.append({'path':str(f.relative_to(root)),'sha256':hashlib.sha256(f.read_bytes()).hexdigest(),'bytes':f.stat().st_size})
assert any('hostap-pq-delay-auth/hostapd-'in r['path']and r['path'].endswith('/hostapd')for r in records)
archive=out/'hostap-final-public-binaries.tar.gz'
with tarfile.open(archive,'w:gz')as tar:
 for f in selected:tar.add(f,arcname=str(f.relative_to(root)),recursive=False)
cmd=['docker','run','--rm','-v',str(root)+':'+str(root)+':ro','tdn-hostap-pq:20261024-v3','sh','-c','openssl version -a; ldd '+str(root/'hostap-pq-delay-auth/hostapd-2.12/hostapd/hostapd')+'; ldd '+str(root/'hostap-pq-delay-auth/wpa_supplicant-2.12/wpa_supplicant/wpa_supplicant')]
r=subprocess.run(cmd,capture_output=True,text=True,timeout=60);assert r.returncode==0,r.stderr
identity=subprocess.run(['docker','image','inspect','--format','{{json .Id}} {{json .RepoTags}} {{json .RepoDigests}} {{.Architecture}} {{.Os}}','tdn-hostap-pq:20261024-v3'],capture_output=True,text=True,check=True)
(out/'collector.source.py').write_bytes(Path(__file__).read_bytes());(out/'observations.json').write_text(json.dumps({'at':datetime.now(timezone.utc).isoformat(),'selected_public_files':records,'runtime_command':cmd,'runtime_stdout':r.stdout,'runtime_stderr':r.stderr,'runtime_image':identity.stdout,'archive_sha256':hashlib.sha256(archive.read_bytes()).hexdigest(),'scope':['Only explicit final public ELF binaries and compile-time .config files are archived. No source-tree test keys, deployment configurations, credential files, private logs or guest overlays are included.','The final EAP v18 binaries include the authenticator callback repair; their hashes must be compared with retained hostap build/runtime observations. Older Docker archives provide linked OpenSSL3.5.5 dependencies but do not contain these later bind-mounted binaries.','The archive preserves exact tested runtime bytes. Rebuilding still requires official hostap2.12 archives and the immutable full patches/configs in hostap-pq-delay-build-v4, hostap-auth-lowest-pn-v5 and hostap-delay-reproduction-v5. No IEEE conformance is inferred.']},indent=2)+'\n');(out/'manifest.json').write_text(json.dumps({'collector_sha256':hashlib.sha256(Path(__file__).read_bytes()).hexdigest(),'files':[{'path':f.name,'sha256':hashlib.sha256(f.read_bytes()).hexdigest(),'bytes':f.stat().st_size}for f in out.iterdir()if f.is_file()]},indent=2)+'\n');print(json.dumps({'files':len(selected),'archive_sha256':hashlib.sha256(archive.read_bytes()).hexdigest(),'bytes':archive.stat().st_size}))
